info.codeblock:
curl -X POST https://api-m.sandbox.paypal.com/v2/checkout/orders \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer A21AAFEpH4PsADbl..." \
  -H "PayPal-Request-Id: order-20240915-001" \
  -d '{
    "intent": "CAPTURE",
    "purchase_units": [
      {
        "reference_id": "store-order-12345",
        "description": "Camera & accessories",
        "amount": {
          "currency_code": "USD",
          "value": "220.00",
          "breakdown": {
            "item_total": {
              "currency_code": "USD",
              "value": "200.00"
            },
            "shipping": {
              "currency_code": "USD",
              "value": "20.00"
            }
          }
        },
        "items": [
          {
            "name": "Sony Alpha Camera",
            "unit_amount": {
              "currency_code": "USD",
              "value": "200.00"
            },
            "quantity": "1",
            "category": "PHYSICAL_GOODS"
          }
        ]
      }
    ],
    "application_context": {
      "brand_name": "Acme Store",
      "landing_page": "LOGIN",
      "shipping_preference": "SET_PROVIDED_ADDRESS",
      "user_action": "PAY_NOW",
      "return_url": "https://acme.com/checkout/success",
      "cancel_url": "https://acme.com/checkout/cancel"
    }
  }'
